import { SystemExit } from './errors.mjs';

export class Action {
  constructor({
    optionStrings = [],
    dest = null,
    nargs = null,
    constValue = undefined,
    defaultValue = null,
    type = null,
    choices = null,
    required = false,
    help = null,
    metavar = null,
  } = {}) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs;
    this.constValue = constValue;
    this.default = defaultValue;
    this.type = type;
    this.choices = choices;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
  }

  call(_parser, namespace, values) {
    namespace[this.dest] = values;
  }
}

export class StoreAction extends Action {
  constructor(options) {
    super(options);
  }
}

export class StoreTrueAction extends Action {
  constructor(options) {
    super({ ...options, nargs: 0, defaultValue: options.defaultValue ?? false });
  }
  call(_parser, namespace) {
    namespace[this.dest] = true;
  }
}

export class HelpAction extends Action {
  constructor(options) {
    super({ ...options, nargs: 0, defaultValue: options.defaultValue });
  }
  call(parser) {
    parser.printHelp();
    throw new SystemExit(0);
  }
}

export const ACTION_CLASSES = {
  store: StoreAction,
  store_true: StoreTrueAction,
  help: HelpAction,
};
