/**
 * Exception types used by the argparse port.
 */

/** Sentinel equivalent to `argparse.SUPPRESS`. */
export const SUPPRESS = '==SUPPRESS==';

/** Raised for an error attributable to a specific argument. */
export class ArgumentError extends Error {
  constructor(argumentName, message) {
    super(argumentName === null || argumentName === undefined
      ? message
      : `argument ${argumentName}: ${message}`);
    this.name = 'ArgumentError';
    this.argumentName = argumentName;
    this.rawMessage = message;
  }
}

/** Raised when a `type=` callable rejects a value. */
export class ArgumentTypeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentTypeError';
  }
}

/**
 * Equivalent of `SystemExit`. The entry point catches it so that library code
 * never calls `process.exit()` behind the caller's back.
 */
export class SystemExit extends Error {
  constructor(code = 0) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
  }
}

/** argparse's `_get_action_name()`. */
export function getActionName(action) {
  if (!action) return null;
  if (action.optionStrings && action.optionStrings.length > 0) {
    return action.optionStrings.join('/');
  }
  if (action.metavar !== null && action.metavar !== undefined && action.metavar !== SUPPRESS) {
    return action.metavar;
  }
  if (action.dest !== null && action.dest !== undefined && action.dest !== SUPPRESS) {
    return action.dest;
  }
